'use client';
import { useEffect, useRef, useState, type KeyboardEvent } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useCopied, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { enter, Seg, Tip } from '../lib/motion';
import '../designme.css';
import './code-viewer.css';

/** k keyword, s string, f function, cm comment, tg tag, at attribute */
export type CodeToken = 'k' | 's' | 'f' | 'cm' | 'tg' | 'at';
/** Plain text, or [token, text] for a highlighted piece */
export type CodePiece = string | [CodeToken, string];

export interface CodeLine {
  /** The line as plain text, or as pieces to highlight */
  code: string | CodePiece[];
  /** The agent changed this line: its number turns green and the line gets a wash */
  changed?: boolean;
  /** What the agent says about the line when you click it */
  note?: string;
}

export interface CodeFile {
  /** Shown on the tab, like "PlanCard.tsx" */
  name: string;
  lines: CodeLine[];
}

export interface CodeViewerProps {
  files: CodeFile[];
  /** The open file, by name. Leave it out to let the tabs switch it */
  file?: string;
  defaultFile?: string;
  onFileChange?: (name: string) => void;
  /** The line whose note is open (0 is the first line), or null. Leave it out to let a click on a line open it */
  line?: number | null;
  defaultLine?: number | null;
  onLineChange?: (line: number | null) => void;
  /** How long a note says "Reading the line" before it answers, in ms */
  delay?: number;
  /** The note for a line the agent didn't change and has nothing to say about */
  unchangedNote?: string;
  /** Called with the file's text when it is copied */
  onCopy?: (text: string) => void;
  className?: string;
}

const TOKEN: Record<CodeToken, string> = { k: 'dm-k', s: 'dm-s', f: 'dm-f', cm: 'dm-cm', tg: 'dm-tg', at: 'dm-at' };
const text = (code: CodeLine['code']) => typeof code === 'string' ? code : code.map(p => typeof p === 'string' ? p : p[1]).join('');

/** The note under a clicked line: it reads for a moment, then crossfades to what the agent says */
function Note({ note, delay }: { note: string; delay: number }) {
  const reduce = useReducedMotion();
  const [phase, setPhase] = useState<'reading' | 'out' | 'said'>('reading');
  useEffect(() => {
    const a = setTimeout(() => setPhase('out'), delay);
    const b = setTimeout(() => setPhase('said'), delay + (reduce ? 0 : 170));
    return () => { clearTimeout(a); clearTimeout(b); };
  }, [delay, reduce]);
  // it opens its own height, so the code under it moves down smoothly instead of jumping
  const box = useRef<HTMLDivElement>(null);
  useIsoLayoutEffect(() => {
    const n = box.current; if (!n || reduce || !n.animate) return;
    const cs = getComputedStyle(n), ease = cs.getPropertyValue('--dm-ease').trim() || 'ease';
    n.animate([{ height: '0px', marginTop: '0px', marginBottom: '0px', paddingTop: '0px', paddingBottom: '0px', opacity: 0, overflow: 'hidden' },
      { height: cs.height, marginTop: cs.marginTop, marginBottom: cs.marginBottom, paddingTop: cs.paddingTop, paddingBottom: cs.paddingBottom, opacity: 1, overflow: 'hidden' }], { duration: 420, easing: ease });
  }, []);
  return (
    <div ref={box} className="dm-cvx-note" aria-live="polite">
      <Icon name="spark" size="xs" />
      <span className={cx('dm-sw', phase === 'out' && 'dm-out')}>{phase === 'said' ? note : <span className="dm-shim">Reading the line</span>}</span>
    </div>
  );
}

/** A file the agent changed, with its changed lines marked. Click a line and the agent explains it. */
export function CodeViewer({ files, file, defaultFile, onFileChange, line, defaultLine = null, onLineChange, delay = 600, unchangedNote = 'Unchanged. The agent kept this line as it was.', onCopy, className }: CodeViewerProps) {
  const [name, setName] = useControllable(file, defaultFile ?? files[0]?.name ?? '', onFileChange);
  const [open, setOpen] = useControllable(line, defaultLine, onLineChange);
  const [copied, copy] = useCopied();
  const cur = files.find(f => f.name === name) ?? files[0];
  const changed = cur?.lines.filter(l => l.changed).length ?? 0;

  const pick = (n: string) => { if (n === name) return; setName(n); setOpen(null); };
  const ask = (k: number) => setOpen(open === k ? null : k);
  const key = (e: KeyboardEvent, k: number) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); ask(k); } };
  const copyFile = () => { const t = cur.lines.map(l => text(l.code)).join('\n'); copy(t); onCopy?.(t); };

  // the card eases to the new file's height rather than keeping room for the longer one
  const reduce = useReducedMotion();
  const body = useRef<HTMLDivElement>(null), was = useRef(0);
  useIsoLayoutEffect(() => {
    const b = body.current; if (!b) return;
    const now = b.offsetHeight, from = was.current; was.current = now;
    if (from && from !== now && !reduce && b.animate) b.animate([{ height: from + 'px', overflow: 'hidden' }, { height: now + 'px', overflow: 'hidden' }], { duration: 420, easing: getComputedStyle(b).getPropertyValue('--dm-ease').trim() || 'ease' });
  }, [cur?.name]);
  useEffect(() => { const b = body.current; if (!b || typeof ResizeObserver === 'undefined') return; const ro = new ResizeObserver(() => { was.current = b.offsetHeight; }); ro.observe(b); return () => ro.disconnect(); }, []);

  return (
    <div data-dm="" className={cx('dm-cvx dm-panel', className)}>
      <div className="dm-cvx-h">
        {/* the files: the library's segmented switch */}
        <Seg options={files.map(f => ({ value: f.name, label: f.name }))} value={cur?.name ?? ''} onChange={pick} label="Files" className="dm-cvx-tabs" />
        <span className="dm-cvx-meta dm-num"><b>+{changed}</b> changed</span>
        <Tip label={copied ? 'Copied to clipboard' : 'Copy'} open={copied}>
          <button type="button" className={cx('dm-ib', copied && 'dm-copied')} aria-label="Copy file" onClick={copyFile}><Icon name={copied ? 'check' : 'copy'} /></button>
        </Tip>
      </div>
      <div ref={body} className="dm-cvx-body">
        <pre className="dm-cvx-code">
          {cur?.lines.map((l, k) => {
            const e = enter(k * 18), on = open === k;
            return [
              <div key={cur.name + k} className={cx('dm-cvx-l', l.changed && 'dm-new', on && 'dm-on', e.className)} style={e.style}
                role="button" tabIndex={0} aria-expanded={on} onClick={() => ask(k)} onKeyDown={ev => key(ev, k)}>
                <span className="dm-n">{k + 1}</span>
                <span className="dm-c">{typeof l.code === 'string' ? l.code || ' ' : l.code.length ? l.code.map((p, j) => typeof p === 'string' ? p : <span key={j} className={TOKEN[p[0]]}>{p[1]}</span>) : ' '}</span>
              </div>,
              on && <Note key={cur.name + k + 'n'} note={l.note ?? unchangedNote} delay={delay} />
            ];
          })}
        </pre>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Code viewer ---------- */
/* a file the agent changed: the file tabs, how many lines changed and Copy in the head; the code under it, each changed line
   marked, and a line's note under it once you click it. Only the code is monospace (no mono in the interface): the files'
   switch, the count and the notes are in the interface's own type. The card is as tall as the file it shows, never
   kept at the longer file's height: switching files eases it to its new height */
.dm-cvx{overflow:hidden;display:flex;flex-direction:column}
/* the head: its controls 16px from the card's sides and top and from the hairline under them */
.dm-cvx-h{display:flex;align-items:center;gap:var(--dm-s-1);padding:var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* the files: the library's segmented switch (as Image generation's Gallery and Styles), scrolling sideways if there are many */
.dm-cvx-tabs{flex:0 1 auto;min-width:0;max-width:100%;overflow-x:auto;scrollbar-width:none}
.dm-cvx-tabs::-webkit-scrollbar{display:none}
.dm-cvx-tabs button{flex:none;white-space:nowrap}
.dm-cvx-meta{margin-left:auto;padding-right:var(--dm-s-1);font-size:12px;color:var(--dm-muted);white-space:nowrap}
.dm-cvx-meta b{font-weight:500;color:var(--dm-ok)}
.dm-cvx .dm-ib{width:28px;height:28px;flex:none}
.dm-cvx .dm-ib.dm-copied{color:var(--dm-ok-mark)!important}
@media (hover:hover) and (pointer:fine){.dm-cvx .dm-ib.dm-copied:hover{color:var(--dm-ok-mark)!important}}
.dm-cvx-body{overflow-x:auto}
.dm-cvx-code{margin:0;padding:var(--dm-s-4) 0;font-family:var(--dm-mono);font-size:12px;line-height:1.8}
.dm-cvx-l{display:flex;padding-right:var(--dm-s-4);cursor:pointer;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-cvx-l:hover{background:var(--dm-row)}}
/* a line that takes the focus fills the scrolling code, which would cut an outside ring: its ring is drawn inside */
.dm-cvx-l:focus-visible{outline-offset:-2px}
.dm-cvx-l.dm-new{background:color-mix(in srgb,var(--dm-ok) 6%,transparent)}
.dm-cvx-l.dm-on{background:var(--dm-sel)}
@media (hover:hover) and (pointer:fine){.dm-cvx-l.dm-on:hover{background:var(--dm-sel)}}
.dm-cvx-l .dm-n{width:46px;text-align:right;padding-right:var(--dm-s-4);color:var(--dm-muted);user-select:none;flex:none;transition:color var(--dm-t-fast)}
.dm-cvx-l.dm-new .dm-n{color:var(--dm-ok)}
.dm-cvx-l.dm-on .dm-n{color:var(--dm-accent-fg,var(--dm-accent))}
.dm-cvx-l .dm-c{white-space:pre}
/* one cool family for the syntax (owner, 4 Nov: the warm and cool mix clashed): violet keywords, blue functions, teal
   components, green strings; attributes and the rest stay in the text greys */
.dm-cvx-code .dm-k{color:var(--dm-pl)}.dm-cvx-code .dm-s{color:var(--dm-pm)}.dm-cvx-code .dm-f{color:var(--dm-pb)}.dm-cvx-code .dm-cm{color:var(--dm-muted);font-style:italic}.dm-cvx-code .dm-tg{color:var(--dm-pt)}.dm-cvx-code .dm-at{color:var(--dm-fg2)}
/* the agent's note belongs to the line it explains (owner, 4 Nov: no grey box): it carries on in that line's tint, like an
   inline review comment. Its spark sits in the line numbers' column, 16px in like the head's first tab, and its words start
   where the code does (the numbers' column is 46px, so a two-digit number starts 16px in too) */
.dm-cvx-note{margin:0;padding:var(--dm-s-1) var(--dm-s-4) var(--dm-s-2) 0;background:var(--dm-sel);font-family:var(--dm-sans);font-size:12.5px;line-height:1.5;white-space:normal;color:var(--dm-fg2);display:grid;grid-template-columns:46px minmax(0,1fr)}
.dm-cvx-note>svg{justify-self:start;margin:3px 0 0 var(--dm-s-4);color:var(--dm-accent-fg,var(--dm-accent))}
.dm-cvx-note .dm-shim{font-size:inherit}
/* Clean: the head is an off-white strip, the files' switch and Copy 16px from the card's edges and the strip's hairline (the
   switch is the library's 30px one, so the strip is 2px taller than a 28px row's, as Line chart's is) */
:root[data-style="clean"] .dm-cvx-h,:root [data-style="clean"] .dm-cvx-h,:root [data-style="clean"].dm-cvx-h{height:calc(30px + 2 * var(--dm-strip-y) + 1px);padding:0 16px;background:var(--dm-strip);border-bottom-color:var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .dm-cvx-l,:root [data-style="clean"] .dm-cvx-l,:root [data-style="clean"].dm-cvx-l{transition:background-color var(--dm-t-fast) var(--dm-ease)}

